import type { ImageSourcePropType } from 'react-native'

/**
 * Silhouette artwork per monster id. Each image is a white shape on a transparent
 * background, tinted at render time. Monsters without art fall back to their Ionicons glyph.
 * Art is generated by scripts/art/<id>.py.
 */
export type MonsterPose = 'idle' | 'hit' | 'hurt'

export interface MonsterPoses {
  idle: ImageSourcePropType
  /** Shown for about 120ms on every strike */
  hit?: ImageSourcePropType
  /** The resting pose at 1/3 HP or less */
  hurt?: ImageSourcePropType
}

export const MONSTER_ART: Record<string, MonsterPoses | undefined> = {
  kobold: {
    idle: require('../../assets/monsters/kobold_idle.png'),
    hit: require('../../assets/monsters/kobold_hit.png'),
    hurt: require('../../assets/monsters/kobold_hurt.png'),
  },
}

/** The picture for a pose, falling back to idle when that pose has no art */
export function artForPose(poses: MonsterPoses, pose: MonsterPose): ImageSourcePropType {
  return poses[pose] ?? poses.idle
}

/** Hurt once HP is at or below a third of max */
export function restingPose(hp: number, max: number): 'idle' | 'hurt' {
  return hp * 3 <= max ? 'hurt' : 'idle'
}
